/* Exported ABI of libadmiral_c.so: the admiral.h C interface, nothing else.
   Hidden visibility alone leaks RTTI. The compiler emits the typeinfo for polymorphic
   template instantiations with default visibility, which exported
   std::thread::_State_impl<...admiral::detail::thread_pool...> and
   std::bad_variant_access. Verified with nm -D --defined-only. */
{
    global:
        adm_*;
        admf_*;
    local:
        *;
};
